    vehicle_services: { name: "Vehicle services", basis: "AAA, Consumer Reports, RepairPal and shop price sheets (2025), rounded; shop labor rates run $110-$200 per hour.", item_count: 22, price_cents: { min: 300, typical: 9500, max: 140000 } },
