  places: {
    harrowmere_estate: {
      id: "harrowmere_estate",
      name: "Harrowmere Estate",
      fields: {
        description: "A low, wet estate of reed beds, drove roads and willows, set on a rise of firmer ground in the fens. The nearest village is Saltreach, two and a half miles away by the causeway.",
        tags: ["region"],
        region: "region_harrowmere_estate"
      },
      timeZone: "Europe/London",
      sceneType: "exploration"
    },
    mere_causeway: {
      id: "mere_causeway",
      name: "The Mere Causeway",
      fields: {
        description: "A raised gravel road across the marsh, covered by the mere at the highest tides. In a hard south-westerly it can be impassable for hours.",
        tags: ["road"]
      },
      parent: "harrowmere_estate",
      sceneType: "exploration"
    },
    saltreach: {
      id: "saltreach",
      name: "Saltreach",
      fields: {
        description: "A small fenland village of brick cottages, a church, a public house and a police constable. The only telephone exchange for miles is in the post office.",
        tags: ["village", "off-map"],
        region: "region_harrowmere_estate"
      },
      timeZone: "Europe/London",
      sceneType: "exploration"
    },
    gatehouse: {
      id: "gatehouse",
      name: "The Gatehouse",
      fields: {
        description: "A brick lodge at the end of the drive, empty since the old gardener retired. The estate's telephone line comes in here before running to the hall on a line of poles.",
        tags: ["lodge"]
      },
      parent: "harrowmere_estate",
      sceneType: "exploration"
    },
    harrowmere_hall: {
      id: "harrowmere_hall",
      name: "Harrowmere Hall",
      fields: {
        description: "A rambling red-brick house with a Jacobean core, Victorian additions and a conservatory that never quite matched either. Wind finds its way into every passage.",
        tags: ["manor"]
      },
      parent: "harrowmere_estate",
      sceneType: "conversation",
      grid: "ground_floor"
    },
    entrance_hall: {
      id: "entrance_hall",
      name: "Entrance Hall",
      fields: {
        description: "A flagged hall with a grandfather clock, a long oak settle and a staircase that creaks on the fourth step. The butler's pantry opens off it.",
        tags: ["hall"]
      },
      parent: "harrowmere_hall",
      sceneType: "conversation",
      cell: { x: 9, y: 10 }
    },
    library: {
      id: "library",
      name: "The Library",
      fields: {
        description: "Walls of leather spines, a worn Turkey carpet, a tray of decanters and a deep fireplace. The mantel is carved with a date in Roman numerals. A door in the east wall leads to the study.",
        tags: ["room"]
      },
      parent: "harrowmere_hall",
      sceneType: "investigation",
      cell: { x: 3, y: 3 }
    },
    study: {
      id: "study",
      name: "Sir Alaric's Study",
      fields: {
        description: "A small, orderly room with a roll-top desk, a portrait of Sir Alaric's father and a framed estate map. A typewriter sits under a cover on a side table.",
        tags: ["room"]
      },
      parent: "harrowmere_hall",
      sceneType: "investigation",
      cell: { x: 9, y: 3 }
    },
    drawing_room: {
      id: "drawing_room",
      name: "The Drawing Room",
      fields: {
        description: "Chintz sofas, a baby grand nobody plays and a tall window onto the drive. After dinner the household gathers here for coffee.",
        tags: ["room"]
      },
      parent: "harrowmere_hall",
      sceneType: "conversation",
      cell: { x: 15, y: 3 }
    },
    dining_room: {
      id: "dining_room",
      name: "The Dining Room",
      fields: {
        description: "A long mahogany table under a dim chandelier, with twelve chairs and a sideboard that is polished every morning whether or not anyone eats.",
        tags: ["room"]
      },
      parent: "harrowmere_hall",
      sceneType: "conversation",
      cell: { x: 3, y: 10 }
    },
    kitchen: {
      id: "kitchen",
      name: "The Kitchen",
      fields: {
        description: "A flagged kitchen with a vast range, copper pans and a scrubbed table where the staff take their meals. A door leads to the yard and another to the cellar steps.",
        tags: ["service"]
      },
      parent: "harrowmere_hall",
      sceneType: "downtime",
      cell: { x: 15, y: 10 }
    },
    conservatory: {
      id: "conservatory",
      name: "The Conservatory",
      fields: {
        description: "A glass-and-iron room of potted palms and wicker chairs. A garden door opens onto a gravel path to the boathouse.",
        tags: ["room"]
      },
      parent: "harrowmere_hall",
      sceneType: "downtime",
      cell: { x: 20, y: 3 }
    },
    upper_floor: {
      id: "upper_floor",
      name: "The Bedroom Corridor",
      fields: {
        description: "A long first-floor corridor with doors to the family and guest bedrooms. Floorboards creak, and a light under a door can be seen from the stairs.",
        tags: ["bedrooms"]
      },
      parent: "harrowmere_hall",
      sceneType: "downtime"
    },
    cellar: {
      id: "cellar",
      name: "The Cellar",
      fields: {
        description: "A cool vaulted cellar of wine racks, coal and trunks. The house's main fuse board is bolted to the wall by the steps.",
        tags: ["cellar"]
      },
      parent: "harrowmere_hall",
      sceneType: "exploration"
    },
    boathouse: {
      id: "boathouse",
      name: "The Boathouse",
      fields: {
        description: "A tarred wooden shed on the edge of the mere with a slipway, a stack of nets and a flat-bottomed punt. A damp path through the reeds leads up to the conservatory.",
        tags: ["water"]
      },
      parent: "harrowmere_estate",
      sceneType: "exploration"
    }
  },
