  maps: {},
  rules: {
    r_storm_breaks: {
      id: "r_storm_breaks",
      on: { at: "clock >= 1290" },
      do: [
        { type: "weather.set", args: { region: "region_harrowmere_estate", state: "storm", minutes: 1800 } },
        { type: "story.flag", args: { name: "storm_active", value: true } },
        { type: "story.flag", args: { name: "phone_working", value: false } }
      ],
      once: true,
      interrupt: true,
      beat: { hint: "The lights flicker, the windows rattle, and someone says it will blow over by morning." }
    },
    r_causeway_floods: {
      id: "r_causeway_floods",
      on: { tick: "slot" },
      do: [
        { type: "space.set_route", args: { route: "rt_causeway_saltreach", open: false } },
        { type: "story.flag", args: { name: "causeway_open", value: false } }
      ],
      when: "flag('storm_active') and flag('causeway_open')",
      once: true,
      beat: { hint: "From the drawing room window the causeway has vanished into a silver sheet." }
    },
    r_night_events: {
      id: "r_night_events",
      on: { at: "clock >= 1385" },
      do: [
        {
          type: "castlife.override",
          args: { who: "julian_ashcombe", place: "library", activity: "a late brandy with the host", minutes: 35 }
        },
        { type: "story.flag", args: { name: "alaric_alive", value: false } },
        { type: "set", args: { entity: "sir_alaric", field: "place", value: "library" } },
        { type: "life", args: { entity: "sir_alaric", to: "dead" } }
      ],
      once: true
    },
    r_night_events_2: {
      id: "r_night_events_2",
      on: { at: "clock >= 1420" },
      do: [{ type: "castlife.override", args: { who: "julian_ashcombe", place: "upper_floor", activity: "going to bed", minutes: 490 } }],
      once: true
    },
    r_study_safe_noticed: {
      id: "r_study_safe_noticed",
      on: { enter: "study" },
      do: [{ type: "link", args: { rel: "knows", from: "pov", to: "study_safe" } }],
      when: "self == pov",
      once: true
    },
    r_body_found: {
      id: "r_body_found",
      on: { at: "clock >= 1880" },
      do: [
        { type: "castlife.override", args: { who: "nell_sparrow", place: "library", minutes: 180 } },
        { type: "story.flag", args: { name: "body_found", value: true } },
        {
          type: "life",
          args: {
            entity: "sir_alaric",
            tell: [
              "pov",
              "lady_honoria",
              "rupert_thorne",
              "verity_lorne",
              "julian_ashcombe",
              "dr_lionel_farrant",
              "gideon_pell",
              "mrs_marsh",
              "nell_sparrow"
            ]
          }
        },
        { type: "note", args: { text: "Nell screams; Pell is first on the scene, then Lady Honoria and the household." } }
      ],
      when: "not flag('alaric_alive')",
      once: true,
      interrupt: true,
      beat: { hint: "A scream from the library cuts through the sound of the gale." }
    },
    r_evidence_burned: {
      id: "r_evidence_burned",
      on: { at: "clock >= 2160" },
      do: [
        { type: "story.flag", args: { name: "ledger_page_intact", value: false } },
        { type: "note", args: { text: "The grate is empty and the library smells of fresh smoke." } }
      ],
      when: "flag('ledger_page_intact')",
      once: true
    },
    r_constable_arrives: {
      id: "r_constable_arrives",
      on: { tick: "slot" },
      do: [
        { type: "castlife.override", args: { who: "constable_hobbs", place: "harrowmere_hall", minutes: 180 } },
        { type: "story.flag", args: { name: "constable_arrived", value: true } }
      ],
      when: "flag('constable_called') or clock >= 3600",
      once: true,
      interrupt: true,
      beat: { hint: "A knock at the front door: a patient man in a cape, rain running off his helmet." }
    },
    r_causeway_reopens: {
      id: "r_causeway_reopens",
      on: { at: "clock >= 3540" },
      do: [
        { type: "weather.set", args: { region: "region_harrowmere_estate", state: "clear", minutes: 180 } },
        { type: "space.set_route", args: { route: "rt_causeway_saltreach", open: true } },
        { type: "story.flag", args: { name: "causeway_open", value: true } },
        { type: "story.flag", args: { name: "storm_active", value: false } }
      ],
      once: true
    },
    r_rupert_defensive: {
      id: "r_rupert_defensive",
      on: { tick: "slot" },
      do: [
        {
          type: "relationships.adjust",
          args: { from: "rupert_thorne", to: "pov", axis: "warmth", delta: -10, why: "Rupert grows hostile." }
        },
        {
          type: "relationships.adjust",
          args: { from: "rupert_thorne", to: "pov", axis: "fear", delta: 5, why: "Rupert is afraid of being found out." }
        },
        { type: "story.flag", args: { name: "asked_whereabouts", value: false } }
      ],
      when: "flag('asked_whereabouts') and at('rupert_thorne', here)",
      cooldownMinutes: 720,
      beat: { hint: "Rupert's smile stays exactly where it is while his eyes go somewhere else." }
    }
  },
