    return [section];
  const parts = [];
  let lines = [];
  let size = 0;
  let fenced = false;
  const flush = () => {
    const text = lines.join(`
`).trim();
    if (text !== "")
      parts.push({ title: `${section.title} (part ${parts.length + 1})`, depth: section.depth, body: text });
    lines = [];
    size = 0;
  };
  for (const line of section.body.split(`
`)) {
    if (/^\s*```/.test(line))
      fenced = !fenced;
    if (!fenced && line.trim() === "" && size >= PART)
      flush();
    lines.push(line);
    size += line.length + 1;
  }
  flush();
