function docs(query, doc) {
  if (doc !== undefined && !hasOwn(docSections, doc))
    return `There is no doc "${doc}". The docs: ${Object.keys(DOCS).join(", ")}.`;
  const sections = doc === undefined ? Object.values(docSections).flat() : docSections[doc] ?? [];
  return lookup(sections, query);
}

