    throw new ToolError(`No chat ${chatId} plays a world. lre_chats lists the chats that do.`);
  if (chat.revision === null)
    throw new ToolError(`LumiRPEngine can't read the state of chat ${chatId}${chat.reason ? ` (${chat.reason})` : ""}, so it can't say which revision the chat plays, or upgrade it.`);
